1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace Tests\Feature\Events;
6	
7	use App\Enums\UserRole;
8	use App\Models\Team;
9	use App\Models\User;
10	use App\Modules\Events\Enums\EventState;
11	use App\Modules\Events\Models\Event;
12	use App\Modules\Events\Models\LandingPage;
13	use Illuminate\Support\Facades\Cache;
14	use Illuminate\Support\Facades\Route;
15	use PHPUnit\Framework\Attributes\Group;
16	use PHPUnit\Framework\Attributes\Test;
17	use Tests\Feature\FeatureTestCase;
18	
19	/**
20	 * Capsule T2 ATDD — shared event page shell adopted by a new and an existing page.
21	 *
22	 * The shell is asserted through its rendered contract (shell root, title region,
23	 * actions region) rather than through class/file names, so any implementation
24	 * that genuinely renders both pages through one shared component passes.
25	 *
26	 * Fails on HEAD: there is no shared shell contract in the rendered output and no
27	 * `events.overview` route.
28	 */
29	#[Group('events')]
30	class EventPageShellAdoptionTest extends FeatureTestCase
31	{
32	    private const SHELL = 'data-testid="event-page-shell"';
33	
34	    private const SHELL_TITLE = 'data-testid="event-page-shell-title"';
35	
36	    private const SHELL_ACTIONS = 'data-testid="event-page-shell-actions"';
37	
38	    private const SETTINGS_TABS = 'data-testid="event-settings-tabs"';
39	
40	    private const EDIT_TAB = 'data-testid="event-settings-tab-edit-details"';
41	
42	    /**
43	     * @return array{0: User, 1: Team}
44	     */
45	    private function adminWithTeam(): array
46	    {
47	        $user = $this->verifiedUser();
48	        $team = Team::factory()->create(['user_id' => $user->id]);
49	        $user->teams()->attach($team, ['role' => UserRole::ADMIN->value]);
50	        $user->forceFill(['current_team_id' => $team->id])->save();
51	
52	        return [$user->fresh(), $team->fresh()];
53	    }
54	
55	    private function eventForTeam(Team $team, User $creator, EventState $state = EventState::DRAFT): Event
56	    {
57	        $event = Event::factory()
58	            ->inState($state)
59	            ->for($team)
60	            ->create(['created_by' => $creator->id]);
61	
62	        $landing = new LandingPage(['event_id' => $event->id, 'template' => 'classic']);
63	        $landing->forceFill(['team_id' => $team->id])->save();
64	
65	        return $event->fresh();
66	    }
67	
68	    /** Literal path so the tests fail on behaviour (404) rather than on route resolution. */
69	    private function overviewUrl(Event $event): string
70	    {
71	        return '/events/'.$event->uuid.'/overview';
72	    }
73	
74	    // -------------------------------------------------------------------------
75	    // AC1 + AC2 — named overview route rendering through the shared shell
76	    // -------------------------------------------------------------------------
77	
78	    #[Test]
79	    public function overview_page_is_reachable_at_the_named_route_and_renders_through_the_shared_shell(): void
80	    {
81	        [$admin, $team] = $this->adminWithTeam();
82	        $event = $this->eventForTeam($team, $admin);
83	
84	        $this->assertTrue(
85	            Route::has('events.overview'),
86	            'A named route events.overview must exist.',
87	        );
88	        $this->assertSame(
89	            $this->overviewUrl($event),
90	            parse_url(route('events.overview', $event->uuid), PHP_URL_PATH),
91	            'events.overview must resolve to GET /events/{event:uuid}/overview.',
92	        );
93	
94	        $this->actingAs($admin)
95	            ->get($this->overviewUrl($event))
96	            ->assertOk()
97	            ->assertSee(self::SHELL, false)
98	            ->assertSee(self::SHELL_TITLE, false)
99	            ->assertSee(self::SHELL_ACTIONS, false)
100	            ->assertSee(self::SETTINGS_TABS, false);
101	    }
102	
103	    // -------------------------------------------------------------------------
104	    // AC3 — Landing Preview retrofitted onto the same shell, behaviour preserved
105	    // -------------------------------------------------------------------------
106	
107	    #[Test]
108	    public function landing_preview_page_renders_through_the_same_shell_without_losing_its_existing_surface(): void
109	    {
110	        [$admin, $team] = $this->adminWithTeam();
111	        $event = $this->eventForTeam($team, $admin);
112	
113	        $this->actingAs($admin)
114	            ->get(route('events.landing.preview', $event->uuid))
115	            ->assertOk()
116	            // Same shared shell contract as the overview page.
117	            ->assertSee(self::SHELL, false)
118	            ->assertSee(self::SHELL_TITLE, false)
119	            ->assertSee(self::SHELL_ACTIONS, false)
120	            ->assertSee(self::SETTINGS_TABS, false)
121	            // Pre-existing preview behaviour other pages/tests depend on.
122	            ->assertSee('data-testid="landing-preview-page"', false)
123	            ->assertSee('data-testid="landing-preview-edit-action"', false)
124	            ->assertSee('data-testid="landing-preview-publish-action"', false);
125	    }
126	
127	    // -------------------------------------------------------------------------
128	    // AC4 — action availability flows from the shared action model into the shell
129	    // -------------------------------------------------------------------------
130	
131	    #[Test]
132	    public function both_pages_drive_action_visibility_from_the_shared_event_action_model(): void
133	    {
134	        [$admin, $team] = $this->adminWithTeam();
135	        $draft = $this->eventForTeam($team, $admin, EventState::DRAFT);
136	        $published = $this->eventForTeam($team, $admin, EventState::PUBLISHED);
137	
138	        // DRAFT: the edit action is available, so the shell surfaces it.
139	        $this->actingAs($admin)
140	            ->get($this->overviewUrl($draft))
141	            ->assertOk()
142	            ->assertSee(self::EDIT_TAB, false);
143	
144	        // PUBLISHED: the shared action model disables editing. A page that did not
145	        // pass availability into the shell would fall back to showing it.
146	        $this->actingAs($admin)
147	            ->get($this->overviewUrl($published))
148	            ->assertOk()
149	            ->assertDontSee(self::EDIT_TAB, false);
150	
151	        $this->actingAs($admin)
152	            ->get(route('events.landing.preview', $published->uuid))
153	            ->assertOk()
154	            ->assertDontSee(self::EDIT_TAB, false);
155	    }
156	
157	    // -------------------------------------------------------------------------
158	    // AC5 — the overview page is read-only
159	    // -------------------------------------------------------------------------
160	
161	    #[Test]
162	    public function overview_page_exposes_no_state_changing_control(): void
163	    {
164	        [$admin, $team] = $this->adminWithTeam();
165	        $event = $this->eventForTeam($team, $admin);
166	
167	        $html = $this->actingAs($admin)
168	            ->get($this->overviewUrl($event))
169	            ->assertOk()
170	            ->assertDontSee('wire:submit', false)
171	            ->getContent();
172	
173	        $this->assertDoesNotMatchRegularExpression(
174	            '/<form\b[^>]*action="[^"]*\/events\/'.preg_quote($event->uuid, '/').'/i',
175	            $html,
176	            'The read-only overview page must not submit to any event route.',
177	        );
178	    }
179	
180	    // -------------------------------------------------------------------------
181	    // AC6 — same view authorization as the other event settings surfaces
182	    // -------------------------------------------------------------------------
183	
184	    #[Test]
185	    public function actor_without_view_access_is_refused_from_the_overview_page(): void
186	    {
187	        [$admin, $team] = $this->adminWithTeam();
188	        $event = $this->eventForTeam($team, $admin);
189	
190	        $billingAdmin = $this->verifiedUser();
191	        $billingAdmin->teams()->attach($team, ['role' => UserRole::BILLING_ADMIN->value]);
192	        $billingAdmin->forceFill(['current_team_id' => $team->id])->save();
193	
194	        [$outsider] = $this->adminWithTeam();
195	
196	        Cache::flush();
197	
198	        // Billing Admin lacks events.view.team — same refusal as events.show.
199	        $this->actingAs($billingAdmin->fresh())
200	            ->get($this->overviewUrl($event))
201	            ->assertForbidden();
202	
203	        // Cross-workspace actor never resolves the event.
204	        $this->actingAs($outsider)
205	            ->get($this->overviewUrl($event))
206	            ->assertNotFound();
207	    }
208	}
