@section('title', __('events.landing.preview.title'))

<div class="events-landing-preview flex h-full flex-col bg-[#F3F0F0]" data-testid="landing-preview-page">
    @php
        $publishAudit = $publishReady['audit'] ?? null;
        $publishAuditStatus = is_array($publishAudit) ? ($publishAudit['status'] ?? null) : null;
        $publishAuditMessage = is_array($publishAudit) ? ($publishAudit['message'] ?? null) : null;
        $publishCtaLabel = match ($publishAuditStatus) {
            'pre_review' => __('events.publish.actions.send_to_review'),
            'pending', 'manual_review' => __('events.publish.actions.review_pending'),
            'needs_changes' => __('events.publish.actions.changes_required'),
            'blocked' => __('events.publish.actions.review_blocked'),
            default => __('events.publish.actions.publish'),
        };
        $publishAuditAlertType = match ($publishAuditStatus) {
            'approved' => 'success',
            'blocked' => 'error',
            'needs_changes' => 'warning',
            default => 'info',
        };
    @endphp

    <div class="shrink-0 bg-[#F3F0F0]">
        <x-events::settings-tabs :event="$event" active="preview" :actions="$eventActions" />
    </div>

    <div class="min-h-0 flex-1 overflow-y-auto p-6">
        {{-- Header --}}
        <div class="mx-auto mb-5 flex w-full max-w-[1100px] flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <h1 class="text-[22px] font-bold text-jako-heading">{{ __('events.landing.preview.title') }}</h1>
            <div class="flex flex-wrap items-center gap-3">
                @if($eventActions['manageLanding']['visible'] ?? false)
                    <x-btn.outline
                        :href="route('events.landing.edit', $event->uuid)"
                        data-testid="landing-preview-edit-action"
                    >
                        {{ __('events.show.links.landing') }}
                    </x-btn.outline>
                @endif

                @if($eventActions['publish']['visible'] ?? false)
                    @if($publishReady['attemptable'] ?? ($publishReady['allowed'] ?? false))
                        <form method="POST" action="{{ route('events.publish', $event->uuid) }}">
                            @csrf
                            <x-btn.primary type="submit" data-testid="landing-preview-publish-action">
                                {{ $publishCtaLabel }}
                            </x-btn.primary>
                        </form>
                    @else
                        <x-btn.primary
                            type="button"
                            disabled
                            aria-disabled="true"
                            title="{{ $publishReady['reason'] ?? __('events.publish.unavailable.unavailable') }}"
                            data-testid="landing-preview-publish-action"
                        >
                            {{ $publishCtaLabel }}
                        </x-btn.primary>
                    @endif
                @endif
            </div>
        </div>

        @if($publishAuditStatus && $publishAuditMessage)
            <x-alert
                :type="$publishAuditAlertType"
                class="mx-auto mb-5 w-full max-w-[1100px]"
                data-testid="landing-preview-publish-audit-status"
                data-status="{{ $publishAuditStatus }}"
            >
                {{ $publishAuditMessage }}
            </x-alert>
        @endif

        {{-- Preview canvas --}}
        <div class="mx-auto w-full max-w-[1100px] rounded-[8px] bg-white p-6">
            @include('events::components.landing-preview', [
                'event' => $event,
                'previewData' => $previewData,
                'rootTestId' => 'landing-preview-page',
            ])
        </div>
    </div>
</div>

