1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Modules\Events\Livewire;
6	
7	use App\Modules\Events\Models\Event;
8	use App\Modules\Events\Services\EventService;
9	use App\Modules\Events\Support\EventActionAvailability;
10	use App\Modules\Events\Support\LandingPreviewPayload;
11	use Livewire\Attributes\Locked;
12	use Livewire\Component;
13	
14	class LandingPreview extends Component
15	{
16	
17	    #[Locked]
18	    public int $eventId;
19	
20	    protected EventService $eventService;
21	
22	    public function boot(EventService $eventService): void
23	    {
24	        $this->eventService = $eventService;
25	    }
26	
27	    public function mount(Event $event): void
28	    {
29	        $this->eventService->authorizeLandingFormAccess($event, authUser());
30	
31	        $this->eventId = $event->getKey();
32	    }
33	
34	    public function render(EventActionAvailability $actionAvailability): mixed
35	    {
36	        $event = $this->eventService->getById($this->eventId)->load(['landingPage', 'speakers']);
37	        $landing = $event->landingPage;
38	
39	        return view('events::livewire.landing-preview', [
40	            'event' => $event,
41	            'previewData' => $landing === null
42	                ? LandingPreviewPayload::build($event, ['template' => 'classic'])
43	                : LandingPreviewPayload::build($event, $landing->toArray()),
44	            'eventActions' => $actionAvailability->for(authUser(), $event),
45	            'publishReady' => $this->eventService->publishReadiness($event, authUser()),
46	        ])
47	            ->extends('layouts.authenticated')
48	            ->section('content');
49	    }
50	}
51

