@endphp

<div
    class="h-full"
    data-testid="event-show"
    data-event-state="{{ $event->state->value }}"
    x-data="{
        cancelAction: null,
        openCancel(action) { this.cancelAction = action; },
        closeCancel() { this.cancelAction = null; },
        @if($event->state === \App\Modules\Events\Enums\EventState::PREPARING && $event->cancelled_at === null)
            preparingPollDelay: 5000,
            preparingPollTimer: null,
            preparingPollController: null,
            preparingPollStopped: false,
            init() { this.schedulePreparingPoll(); },
            destroy() {
                this.preparingPollStopped = true;
                window.clearTimeout(this.preparingPollTimer);
                this.preparingPollController?.abort();
            },
            schedulePreparingPoll() {
                if (this.preparingPollStopped) return;
                window.clearTimeout(this.preparingPollTimer);
                this.preparingPollTimer = window.setTimeout(() => this.checkPreparingState(), this.preparingPollDelay);
            },
            preparingPollIsDeferred() {
                const activeElement = document.activeElement;
                return document.hidden
                    || this.cancelAction !== null
                    || activeElement?.matches('input:not([type=hidden]), textarea, select');
            },
            async checkPreparingState() {
                if (this.preparingPollIsDeferred()) {
                    this.schedulePreparingPoll();
                    return;
                }

                const controller = new AbortController();
                this.preparingPollController = controller;

                try {
                    const response = await window.fetch(window.location.href, {
                        credentials: 'same-origin',
                        headers: { Accept: 'text/html' },
                        signal: controller.signal,
                    });
                    const html = response.ok ? await response.text() : '';
                    const nextDocument = new DOMParser().parseFromString(html, 'text/html');
                    const nextState = nextDocument
                        .querySelector('[data-testid=event-show]')
                        ?.dataset.eventState;
                    const nextPreparingPollEnabled = nextDocument
                        .querySelector('[data-testid=event-preparing-auto-refresh]') !== null;

                    if (
                        nextState
                        && (nextState !== this.$el.dataset.eventState || ! nextPreparingPollEnabled)
                        && ! this.preparingPollIsDeferred()
                    ) {
                        window.location.reload();
                        return;
                    }
                } catch (error) {
                    // A transient failure must not replace the server as state authority.
                } finally {
                    if (this.preparingPollController === controller) this.preparingPollController = null;
                }

                this.schedulePreparingPoll();
            },
        @endif
    }"
